<script setup lang="ts">
import {connectDaymark} from './realtime';
import {ref,computed,onMounted,watch,onBeforeUnmount} from 'vue';
import AdminDialog from '../../AdminDialog.vue';import Pagination from '../../CvBankPagination.vue';import Editor from './DaymarkEditor.vue';import './daymark.css';
const props=defineProps<{csrf?:string}>();
const today=new Date().toLocaleDateString('en-CA'),month=ref(today.slice(0,7)),date=ref(today),company=ref(''),employee=ref(''),department=ref(''),status=ref(''),search=ref(''),page=ref(1),size=ref(12),monthlyTab=ref('people');
const reportFilter=ref('');
const mobileNav=ref(false),inlineDepartmentName=ref(''),addingDepartment=ref(false),reportReady=ref(false);
let restoringFilters=false,reportNavigation=false;
const savingReport=ref(''),downloading=ref('');
const realtimeState=ref('connecting');let disconnectRealtime:(()=>void)|undefined,realtimeRefreshing=false,realtimePending=false;
const section=ref(location.hash.slice(1)||'overview'),data=ref<any>(null),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),noticeError=ref(false),modalError=ref(''),dialog=ref(''),form=ref<any>({}),selected=ref<any>(null),invitations=ref<any[]>([]),inviteLink=ref('');let reportBaseline='';
let timer:ReturnType<typeof setTimeout>|undefined,loadVersion=0,ownVersion=0;
const labels:Record<string,string>={overview:'Overview',reports:'Daily reports',monthly:'Monthly overview',people:'People',companies:'Companies',departments:'Departments',invitations:'Invitations',roles:'Roles & access',audit:'Activity log',account:'My account',settings:'Settings'};
const roleLabels:Record<string,string>={super_admin:'Super Admin',company_admin:'Company Admin',ceo:'CEO',md:'Managing Director',hr:'Human Resources',pm:'Project Manager',om:'Operations Manager',employee:'Employee'};
const fields=[['completed','Completed tasks'],['progress','Work in progress'],['plan','Next plan'],['blockers','Hurdles & blockers']];const statuses=['draft','submitted','reviewed','changes_requested'];
const can=(ability:string)=>data.value?.permissions.includes(ability);const companyName=(id:number)=>data.value?.companies.find((c:any)=>c.id===id)?.name||'Company';const textLabel=(value:string)=>value.replace(/_/g,' ').replace(/\b\w/g,(c:string)=>c.toUpperCase());
const personalView=computed(()=>data.value?.viewer.role==='employee');
const reportTitle=computed(()=>!reportReady.value?'Your daily report':!form.value.id?'New daily report':form.value.status==='draft'?'Continue your draft':form.value.status==='submitted'?'Submitted daily report':form.value.status==='changes_requested'?'Changes requested':'Reviewed daily report');
const reportHelp=computed(()=>!form.value.id?'Complete your update, then save a private draft or submit it for review.':form.value.status==='draft'?'This is your saved draft. Only you can see it until you submit it.':form.value.status==='submitted'?'You have already submitted this report for review. Changes here update the same report; they do not create another report.':form.value.status==='changes_requested'?'Your reviewer has requested changes. Update this report and resubmit it for review.':'This report has been reviewed and is locked. You can read it below.');
const reportButton=computed(()=>form.value.status==='submitted'?'Update submitted report':form.value.status==='changes_requested'?'Resubmit for review':form.value.status==='reviewed'?'Reviewed - read only':'Submit report');
const navigation=computed(()=>[['overview','view_reports'],['reports','view_reports'],['monthly','view_reports'],['audit','view_audit'],['account','view_reports']].filter(([,ability])=>can(ability)));
const drillLabels:Record<string,string>={shared:'Submitted reports contributing to your hours',blockers:'Reports with blockers',today:'Reports submitted today'};
const shown=computed(()=> (data.value?.reports||[]).filter((r:any)=>(!reportFilter.value||r.status!=='draft'&&(reportFilter.value!=='blockers'||blocked(r))&&(reportFilter.value!=='today'||r.date===today))&&(!company.value||r.company_id===Number(company.value))&&(!employee.value||r.user_id===Number(employee.value))&&(!department.value||r.department===department.value)&&(!status.value||r.status===status.value)&&[r.name,...Object.values(r.sections_text||{})].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const people=computed(()=>(data.value?.users||[]).filter((u:any)=>(!company.value||u.company_id===Number(company.value))&&(!employee.value||u.id===Number(employee.value))&&(!department.value||u.department===department.value)&&[u.name,u.email,u.department].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const rows=computed(()=>section.value==='monthly'&&!personalView.value&&monthlyTab.value==='people'?people.value:section.value==='people'?people.value:section.value==='audit'?data.value?.audit||[]:section.value==='invitations'?invitations.value:section.value==='departments'?(data.value?.departments||[]).filter((d:any)=>!company.value||d.company_id===Number(company.value)):shown.value);
const paged=computed(()=>rows.value.slice((page.value-1)*size.value,page.value*size.value));const submitted=computed(()=>shown.value.filter((r:any)=>r.status!=='draft'));const hours=computed(()=>submitted.value.reduce((sum:number,r:any)=>sum+Number(r.hours),0));
const departments=computed(()=>[...new Set<string>((data.value?.users||[]).filter((u:any)=>!company.value||u.company_id===Number(company.value)).map((u:any)=>u.department).filter(Boolean))].sort());
const weekCounts=computed(()=>Array.from({length:5},(_,i)=>({label:'Week '+(i+1),count:submitted.value.filter((r:any)=>Math.min(4,Math.floor((Number(r.date.slice(8,10))-1)/7))===i).length})));
function blocked(r:any){return !['','none','no','n/a','no blockers','none.','no blockers.'].includes((r.sections_text?.blockers||'').trim().toLowerCase());}
function summary(id:number){const reports=submitted.value.filter((r:any)=>r.user_id===id);return {days:reports.length,hours:reports.reduce((s:number,r:any)=>s+Number(r.hours),0),reviewed:reports.filter((r:any)=>r.status==='reviewed').length,blockers:reports.filter(blocked).length};}
function notify(message:string,failed=false){notice.value=message;noticeError.value=failed;clearTimeout(timer);timer=setTimeout(()=>notice.value='',4500);}
async function api(path:string,body?:any){const response=await fetch('/daymark/api/'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Unable to complete the action.');return result;}
async function load(){const version=++loadVersion;loading.value=true;error.value='';try{const query=new URLSearchParams(section.value==='reports'?{date:date.value}:{month:month.value});const result=await api('data?'+query);if(version!==loadVersion)return;data.value=result;if(!navigation.value.some(([key])=>key===section.value))section.value='overview';}catch(e){if(version===loadVersion)error.value=(e as Error).message;}finally{if(version===loadVersion)loading.value=false;}}
function go(key:string){mobileNav.value=false;section.value=key;page.value=1;location.hash=key;}
const savedFilters:Record<string,any>={};
function openDashboardReports(kind:string){
 savedFilters.monthly={month:month.value,status:['draft','submitted','reviewed','changes_requested'].includes(kind)?kind:'',reportFilter:['shared','blockers','today'].includes(kind)?kind:''};
 monthlyTab.value='reports';go('monthly');
}
watch(section,(next,previous)=>{
 restoringFilters=true;
 savedFilters[previous]={company:company.value,employee:employee.value,department:department.value,status:status.value,search:search.value,date:date.value,month:month.value,reportFilter:reportFilter.value};
 const state=savedFilters[next]||{};reportFilter.value=state.reportFilter||'';
 company.value=state.company||'';employee.value=state.employee||'';department.value=state.department||'';status.value=state.status||'';search.value=state.search||'';date.value=state.date||today;month.value=state.month||today.slice(0,7);restoringFilters=false;page.value=1;if(!reportNavigation)void load();
},{flush:'sync'});
watch([date,month],()=>{if(!restoringFilters&&!reportNavigation){page.value=1;void load();}},{flush:'sync'});watch([company,employee,department,status,search,monthlyTab,reportFilter],()=>page.value=1);
function open(kind:string,value:any={}){reportBaseline='';inlineDepartmentName.value='';addingDepartment.value=false;reportReady.value=false;modalError.value='';dialog.value=kind;form.value={...value,...(kind==='daily-export'?{export_company:company.value,export_department:department.value}:{})};}
function reportSnapshot(){return JSON.stringify([form.value.date,form.value.hours,...fields.map(([key])=>form.value[key])]);}
function close(){if(dialog.value==='report'&&reportBaseline&&reportBaseline!==reportSnapshot()&&!confirm('Discard unsaved report changes?'))return;if(!busy.value){dialog.value='';selected.value=null;ownVersion++;}}
async function submit(path:string,body:any,message:string,refresh=true){if(busy.value)return;busy.value=true;modalError.value='';try{const result=await api(path,body);dialog.value='';selected.value=null;notify(result.message||message);if(refresh)await load();return result;}catch(e){modalError.value=(e as Error).message;notify(modalError.value,true);}finally{busy.value=false;}}
async function reportDate(value:string){if(!value||value>today)return;if(reportBaseline&&reportBaseline!==reportSnapshot()&&!confirm('Changing the date will discard unsaved changes. Continue?')){document.querySelector<HTMLInputElement>('.dm-dialog input[type=date]')!.value=form.value.date;return;}const version=++ownVersion;reportReady.value=false;busy.value=true;modalError.value='';try{const existing=(await api('own-report?date='+encodeURIComponent(value))).report;if(version!==ownVersion)return;form.value={date:value,hours:8,completed:'',progress:'',plan:'',blockers:'',...existing};if(existing)for(const [key] of fields)form.value[key]=existing.sections_html[key];reportBaseline=reportSnapshot();reportReady.value=true;}catch(e){modalError.value=(e as Error).message;}finally{if(version===ownVersion)busy.value=false;}}
function newReport(){open('report');void reportDate(today);}
async function saveReport(state:string){
 if(busy.value||!reportReady.value||form.value.status==='reviewed')return;
 const savedDate=form.value.date;savingReport.value=state;
 try{const result=await submit('report',{...form.value,status:state,content_format:'html'},state==='draft'?'Private draft saved.':'Report submitted.',false);
 if(result){reportNavigation=true;try{go('reports');date.value=savedDate;company.value='';employee.value='';department.value='';status.value='';search.value='';savedFilters.reports={date:savedDate};}finally{reportNavigation=false;}await load();}}
 finally{savingReport.value='';}
}
function viewReport(report:any){selected.value=report;open('review',{id:report.id,feedback:report.feedback||'',status:'reviewed'});}
function editOwn(){const report=selected.value;open('report');selected.value=null;void reportDate(report.date);}
function newPersonInvite(){inviteLink.value='';open('invite',{company_id:data.value.viewer.company_id||data.value.companies[0]?.id||'',name:'',email:'',department_id:'',designation:'',role:'employee',custom_role_id:null,manager_ids:[],delivery_method:'manual'});}
function managePerson(user:any){open('person',{...user,department_id:data.value.departments.find((d:any)=>d.company_id===user.company_id&&d.name===user.department)?.id||'',custom_role_id:user.custom_role_id||null,manager_ids:data.value.assignments.filter((a:any)=>a.employee_id===user.id).map((a:any)=>a.manager_id)});}
async function invite(){const result=await submit('invite',form.value,'Invitation created.');if(result)inviteLink.value=result.invitation_url;}
function newRole(role:any=null){open('role',role?{...role,permissions:[...role.permissions]}:{company_id:data.value.viewer.company_id||data.value.companies[0]?.id||'',name:'',base_role:'employee',permissions:['view_reports','write_reports','export_reports','view_companies']});}
const roleAbilities=computed(()=>data.value?.role_matrix?.roles.find((r:any)=>r.role===form.value.base_role)?.permissions||[]);
function ownDraft(report:any){return report.user_id===data.value?.viewer.id&&report.status!=='reviewed'&&can('write_reports');}
async function download(kind:string,format:string){if(busy.value||downloading.value)return;downloading.value=kind+':'+format;busy.value=true;try{const q=new URLSearchParams({format,company:kind==='daily-export'?form.value.export_company:company.value,department:kind==='daily-export'?form.value.export_department:department.value,...(kind==='daily-export'?{date:form.value.date||date.value}:section.value==='reports'?{date:date.value,employee:employee.value,status:status.value}:{month:month.value,employee:employee.value,status:status.value})});const response=await fetch('/daymark/api/'+kind+'?'+q,{headers:{Accept:'application/json'}});if(!response.ok){const result=await response.json();throw Error(result.message||'Export failed.');}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='daymark-'+(kind==='daily-export'?(form.value.date||date.value):section.value==='reports'?date.value:month.value)+'.'+format;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Report downloaded.');}catch(e){notify((e as Error).message,true);}finally{busy.value=false;downloading.value='';}}
const exportDepartments=computed(()=>[...new Set<string>((data.value?.users||[]).filter((u:any)=>!form.value.export_company||u.company_id===Number(form.value.export_company)).map((u:any)=>u.department).filter(Boolean))].sort());
async function createInlineDepartment(){
 if(busy.value)return;
 const name=inlineDepartmentName.value.trim();if(!name){modalError.value='Enter a department name.';return;}
 busy.value=true;modalError.value='';
 try{const result=await api('departments',{company_id:form.value.company_id,name});data.value.departments=[...data.value.departments.filter((d:any)=>d.id!==result.department.id),result.department].sort((a:any,b:any)=>a.name.localeCompare(b.name));form.value.department_id=result.department.id;inlineDepartmentName.value='';addingDepartment.value=false;notify('Department saved and selected.');}
 catch(e){modalError.value=(e as Error).message;}finally{busy.value=false;}
}
async function openFollowup(item:any){
 dialog.value='';selected.value=null;go('reports');date.value=item.date;company.value='';employee.value='';department.value='';status.value='';search.value='';await load();
 const report=data.value?.reports.find((r:any)=>r.id===item.id);if(!error.value&&report)viewReport(report);else if(!error.value)notify('This report is no longer available in your reporting scope.',true);
}
async function refreshFromRealtime(){
 realtimePending=true;if(realtimeRefreshing||busy.value)return;
 realtimeRefreshing=true;
 try{while(realtimePending&&!busy.value){realtimePending=false;await load();
  if(dialog.value==='review'&&selected.value){const latest=data.value?.reports.find((r:any)=>r.id===selected.value.id);if(latest)selected.value=latest;else{dialog.value='';selected.value=null;}}
  if(dialog.value==='report'&&form.value.id){const editedId=form.value.id,editedDate=form.value.date;try{const latest=(await api('own-report?date='+encodeURIComponent(editedDate))).report;if(dialog.value==='report'&&form.value.id===editedId&&form.value.date===editedDate&&latest){form.value.status=latest.status;form.value.feedback=latest.feedback;}}catch(e){notify((e as Error).message,true);}}
 }}finally{realtimeRefreshing=false;}
}
function startRealtime(){disconnectRealtime?.();disconnectRealtime=connectDaymark(()=>props.csrf||'',()=>void refreshFromRealtime(),state=>realtimeState.value=state,()=>void refreshFromRealtime());}
watch(busy,value=>{if(!value&&realtimePending)void refreshFromRealtime();});
function syncHash(){const key=location.hash.slice(1);if(labels[key]&&section.value!==key)section.value=key;}
onMounted(()=>{void load();startRealtime();window.addEventListener('hashchange',syncHash);});onBeforeUnmount(()=>{disconnectRealtime?.();clearTimeout(timer);loadVersion++;ownVersion++;window.removeEventListener('hashchange',syncHash);});
</script>
<template><div class="dm-workspace"><div v-if="notice" class="judibas-toast" :class="{error:noticeError}" role="status"><span class="judibas-toast-dot"></span>{{notice}}</div>
<header class="dm-product-heading"><div><p class="eyebrow">JUDIBAS / TEAM REPORTING</p><div class="dm-title-row"><h1>Daymark</h1><span class="dm-live-status" :class="realtimeState" role="status"><i aria-hidden="true"></i>{{realtimeState==='live'?'Live':realtimeState==='connecting'?'Connecting':realtimeState==='reconnecting'?'Reconnecting':realtimeState==='disabled'?'Live updates disabled':'Connection unavailable'}}</span></div><p class="muted">{{personalView?'Your daily updates, progress and feedback.':'Daily progress. Clear priorities. Connected teams.'}}</p></div><button v-if="can('write_reports')" class="button primary" @click="newReport">＋ Write report</button></header>
<p v-if="error" class="notice admin-error" role="alert">{{error}} <button class="button" @click="load">Try again</button></p><p v-if="!data&&loading" role="status">Loading Daymark…</p>
<div v-if="data" class="dm-layout"><aside class="dm-sidebar"><button class="dm-mobile-nav" :aria-expanded="mobileNav" aria-controls="daymark-navigation" @click="mobileNav=!mobileNav"><span>Navigation ? {{labels[section]}}</span><span aria-hidden="true">{{mobileNav?'?':'+'}}</span></button><p class="eyebrow">WORKSPACE</p><nav id="daymark-navigation" aria-label="Daymark navigation" :class="{open:mobileNav}"><button v-for="[key] in navigation" :key="key" :class="{active:section===key}" :aria-current="section===key?'page':undefined" @click="go(key)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path :d="key==='overview'?'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z':key==='people'?'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2':key==='companies'||key==='departments'?'M4 21V3h12v18 M16 10h4v11 M2 21h20 M8 7h4 M8 11h4 M8 15h4':'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5'"/></svg>{{personalView&&key==='reports'?'My daily reports':personalView&&key==='monthly'?'My monthly reports':labels[key]}}</button><a v-if="data.viewer.role==='super_admin'" href="/admin#daymark-setup">Administration</a><a href="/products">← All products</a></nav><div class="dm-scope"><strong>{{data.viewer.name}}</strong><small>{{roleLabels[data.viewer.role]||data.viewer.role_name}}</small><small>{{data.viewer.role==='super_admin'?'All companies':companyName(data.viewer.company_id)}}</small></div></aside>
<main class="dm-main" :aria-busy="loading"><header class="dm-section-heading"><div><h2>{{personalView?(section==='overview'?'Your reporting overview':section==='reports'?'My daily reports':section==='monthly'?'My monthly reports':labels[section]):section==='overview'?'A clear view of your day.':labels[section]}}</h2><p class="muted">{{personalView&&['overview','reports','monthly'].includes(section)?'Track your reports, review status and feedback.':section==='overview'?'A clear picture of progress across your reporting scope.':section==='reports'?'Daily updates, feedback and next steps.':section==='monthly'?'Explore monthly progress by person and report.':section==='people'?'Company roles and reporting assignments.':section==='departments'?'Organise your reporting teams by company.':section==='roles'?'Define permissions within each reporting role’s data scope.':section==='audit'?'Who changed what, and when.':'Your shared Judibas workspace.'}}</p></div><div class="dm-actions"><button v-if="section==='departments'&&can('manage_departments')" class="button primary" @click="open('department',{company_id:data.viewer.company_id||data.companies[0]?.id||'',name:''})">＋ Add department</button><button v-if="section==='roles'&&can('manage_roles')" class="button primary" @click="newRole()">＋ Create role</button><button v-if="section==='invitations'&&can('manage_invitations')" class="button primary" @click="newPersonInvite">＋ Invite person</button><a v-if="section==='companies'&&data.viewer.role==='super_admin'" href="/admin#companies" class="button">Manage companies ↗</a></div></header>
<section v-if="section==='overview'" class="dm-welcome"><div><p class="eyebrow">PROGRESS, IN PERSPECTIVE</p><h3>{{personalView?'Your work, clearly reported.':'Every update moves us forward.'}}</h3><p v-if="personalView">Record your progress, track submitted reports and respond to reviewer feedback.</p><p v-else>Your people, their priorities, and the progress that matters.<br>Everything you need to stay in sync.</p></div><svg viewBox="0 0 180 120" fill="none" aria-hidden="true"><rect x="24" y="30" width="112" height="72" rx="12"/><rect x="46" y="12" width="112" height="72" rx="12"/><path d="m64 43 9 9 17-18 M102 39h37 M102 51h25 M64 67h75"/></svg></section><div v-if="['overview','reports','monthly','people','departments'].includes(section)" class="dm-filters"><label v-if="section==='reports'">Report date<input type="date" v-model="date" :max="today"></label><label v-else-if="['overview','monthly'].includes(section)">Month<input type="month" v-model="month"></label><label v-if="!personalView">Company<select v-model="company" @change="employee='';department=''"><option value="">All accessible companies</option><option v-for="c in data.companies" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label><label v-if="!personalView&&section!=='departments'">Department<select v-model="department"><option value="">All departments</option><option v-for="d in departments" :key="d">{{d}}</option></select></label><template v-if="['reports','monthly'].includes(section)"><label v-if="!personalView">Person<select v-model="employee"><option value="">All accessible people</option><option v-for="u in data.users.filter((u:any)=>!company||u.company_id===Number(company))" :key="u.id" :value="String(u.id)">{{u.name}}</option></select></label><label>Status<select v-model="status"><option value="">All statuses</option><option v-for="s in statuses" :key="s" :value="s">{{textLabel(s)}}</option></select></label></template><label v-if="section!=='departments'">Search<input v-model="search" type="search" :placeholder="personalView?'Search your reports':'Search people or reports'"></label></div>
<template v-if="section==='overview'"><div class="dm-stats"><article v-if="personalView"><button type="button" class="dm-stat-link" @click="openDashboardReports('draft')"><small>Private drafts</small><strong>{{shown.filter((r:any)=>r.status==='draft').length}}</strong><span>Only visible to you</span></button></article><article v-else><small>People in scope</small><strong>{{people.filter((u:any)=>u.active).length}}</strong><span>Active reporting profiles</span></article><article><component :is="personalView?'button':'div'" :type="personalView?'button':undefined" class="dm-stat-link" @click="personalView&&openDashboardReports('shared')"><small>Reports this month</small><strong>{{submitted.length}}</strong><span>{{personalView?'Your submitted updates':'Shared with your team'}}</span></component></article><article><component :is="personalView?'button':'div'" :type="personalView?'button':undefined" class="dm-stat-link" @click="personalView&&openDashboardReports('submitted')"><small>Awaiting review</small><strong>{{submitted.filter((r:any)=>r.status==='submitted').length}}</strong><span>Submitted reports</span></component></article><article><component :is="personalView?'button':'div'" :type="personalView?'button':undefined" class="dm-stat-link" @click="personalView&&openDashboardReports('blockers')"><small>Reports with blockers</small><strong>{{submitted.filter(blocked).length}}</strong><span>May need follow-up</span></component></article></div><div class="dm-overview-grid"><section class="dm-panel"><header><h3>{{personalView?'Your reporting activity':"Your team’s reporting rhythm"}}</h3><span class="muted">{{month}}</span></header><div class="dm-chart"><div v-for="week in weekCounts" :key="week.label"><span>{{week.label}}</span><div><i :style="{width:(week.count?Math.max(4,100*week.count/Math.max(1,...weekCounts.map(w=>w.count))):0)+'%'}"></i></div><strong>{{week.count}}</strong></div></div></section><section class="dm-panel"><header><h3>At a glance</h3></header><div class="dm-summary"><component :is="personalView?'button':'p'" :type="personalView?'button':undefined" @click="personalView&&openDashboardReports('shared')"><span>Hours reported</span><strong>{{hours.toFixed(1)}} h</strong></component><component :is="personalView?'button':'p'" :type="personalView?'button':undefined" @click="personalView&&openDashboardReports('reviewed')"><span>Reviewed reports</span><strong>{{submitted.filter((r:any)=>r.status==='reviewed').length}}</strong></component><component :is="personalView?'button':'p'" :type="personalView?'button':undefined" @click="personalView&&openDashboardReports('changes_requested')"><span>Changes requested</span><strong>{{submitted.filter((r:any)=>r.status==='changes_requested').length}}</strong></component><component :is="personalView?'button':'p'" :type="personalView?'button':undefined" @click="personalView&&openDashboardReports('today')"><span>Submitted today</span><strong>{{submitted.filter((r:any)=>r.date===today).length}}</strong></component></div></section></div><section v-if="data.action_items.length" class="dm-panel"><header><h3>Follow-up needed</h3></header><button v-for="item in data.action_items" :key="item.id" class="dm-followup" @click="openFollowup(item)"><strong>{{item.name}}</strong><span>{{item.date}} · {{textLabel(item.status)}}</span><span>{{item.feedback||'Open this report to follow up.'}}</span></button></section><section class="dm-panel"><header><h3>{{personalView?'Your latest reports':'Latest updates'}}</h3><button class="button" @click="go('monthly');monthlyTab='reports'">View all reports →</button></header><div v-if="!shown.length" class="dm-empty">No reports for this selection.</div><div v-for="r in shown.slice(0,5)" :key="r.id" class="dm-latest"><div><strong>{{personalView?r.date:r.name}}</strong><small>{{personalView?Number(r.hours).toFixed(1)+' hours':r.department+' / '+r.date}}</small></div><span class="dm-badge" :class="r.status">{{textLabel(r.status)}}</span><button class="button" @click="viewReport(r)">View report</button></div></section></template>
<template v-else-if="['reports','monthly'].includes(section)"><div v-if="section==='monthly'" class="dm-stats"><article><small>Submitted days</small><strong>{{submitted.length}}</strong></article><article><small>Hours reported</small><strong>{{hours.toFixed(1)}}</strong></article><article><small>Reviewed</small><strong>{{submitted.filter((r:any)=>r.status==='reviewed').length}}</strong></article><article><small>With blockers</small><strong>{{submitted.filter(blocked).length}}</strong></article></div><p v-if="reportFilter" class="dm-filter-context">{{drillLabels[reportFilter]}} <button type="button" class="button" @click="reportFilter=''">Show all reports</button></p><div class="dm-toolbar"><div v-if="section==='monthly'&&!personalView" class="dm-tabs" role="tablist" aria-label="Monthly views"><button v-for="tab in ['people','reports']" :key="tab" role="tab" :aria-selected="monthlyTab===tab" :class="{active:monthlyTab===tab}" @click="monthlyTab=tab">{{tab==='people'?'People summary':'Monthly reports'}}</button></div><div v-if="can('export_reports')" class="dm-actions"><button class="button" :disabled="busy" :aria-busy="downloading==='export:csv'" @click="download('export','csv')"><span v-if="downloading==='export:csv'" class="dm-spinner" aria-hidden="true"></span>{{downloading==='export:csv'?'Preparing CSV...':'Export CSV'}}</button><button class="button" :disabled="busy" :aria-busy="downloading==='export:xlsx'" @click="download('export','xlsx')"><span v-if="downloading==='export:xlsx'" class="dm-spinner" aria-hidden="true"></span>{{downloading==='export:xlsx'?'Preparing Excel...':'Export Excel'}}</button><button v-if="!personalView" class="button" :disabled="busy" @click="open('daily-export',{date:date})">Day-end report</button></div></div><section class="dm-panel dm-table-panel"><div class="dm-table-scroll"><table v-if="section==='monthly'&&!personalView&&monthlyTab==='people'"><thead><tr><th>Person</th><th>Company</th><th>Submitted days</th><th>Hours</th><th>Reviewed</th><th>With blockers</th></tr></thead><tbody><tr v-for="u in paged" :key="u.id"><td><strong>{{u.name}}</strong><small>{{u.department}}</small></td><td>{{companyName(u.company_id)}}</td><td>{{summary(u.id).days}}</td><td>{{summary(u.id).hours.toFixed(1)}}</td><td>{{summary(u.id).reviewed}}</td><td>{{summary(u.id).blockers}}</td></tr></tbody></table><table v-else><thead><tr><th v-if="!personalView">Team member</th><th v-if="!personalView">Company</th><th>Date</th><th>Status</th><th>Hours</th><th>Blockers</th><th>Actions</th></tr></thead><tbody><tr v-for="r in paged" :key="r.id"><td v-if="!personalView"><strong>{{r.name}}</strong><small>{{r.department}}</small></td><td v-if="!personalView">{{companyName(r.company_id)}}</td><td>{{r.date}}</td><td><span class="dm-badge" :class="r.status">{{textLabel(r.status)}}</span></td><td>{{Number(r.hours).toFixed(1)}} h</td><td>{{blocked(r)?'Needs attention':'None'}}</td><td><button class="button" @click="viewReport(r)">View report ↗</button></td></tr></tbody></table></div><p v-if="!rows.length" class="dm-empty">No reports match this selection.</p><Pagination v-model:page="page" v-model:page-size="size" :total="rows.length"/></section></template>
<template v-else-if="section==='people'"><p v-if="data.viewer.role==='super_admin'" class="muted">Create accounts and assign products in <a href="/admin#users">Administration → Users</a>. Configure reporting access here.</p><section class="dm-panel dm-table-panel"><div class="dm-table-scroll"><table><thead><tr><th>Person</th><th>Company / Department</th><th>Reporting role</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="u in paged" :key="u.id"><td><strong>{{u.name}}</strong><small>{{u.email}}</small></td><td>{{companyName(u.company_id)}}<small>{{u.department}} · {{u.designation}}</small></td><td>{{u.role_name||roleLabels[u.role]}}</td><td><span class="dm-badge" :class="u.active?'reviewed':'draft'">{{u.active?'Active':'Inactive'}}</span></td><td><button v-if="can('manage_roles')&&u.id!==data.viewer.id" class="button" @click="managePerson(u)">Manage</button></td></tr></tbody></table></div><p v-if="!rows.length" class="dm-empty">No people match this selection.</p><Pagination v-model:page="page" v-model:page-size="size" :total="rows.length"/></section></template>
<template v-else-if="section==='companies'"><div class="dm-company-grid"><button v-for="c in data.companies" :key="c.id" class="dm-panel dm-company" @click="savedFilters.monthly={company:String(c.id)};go('monthly')"><span class="dm-company-icon">{{c.name.slice(0,2).toUpperCase()}}</span><h3>{{c.name}}</h3><p>{{data.users.filter((u:any)=>u.company_id===c.id).length}} people in your scope</p><span>View reports →</span></button></div><p v-if="!data.companies.length" class="dm-empty">No companies assigned.</p></template>
<template v-else-if="section==='departments'"><section class="dm-panel dm-table-panel"><div class="dm-table-scroll"><table><thead><tr><th>Department</th><th>Company</th><th>People</th><th>Actions</th></tr></thead><tbody><tr v-for="d in paged" :key="d.id"><td><strong>{{d.name}}</strong></td><td>{{companyName(d.company_id)}}</td><td>{{data.users.filter((u:any)=>u.company_id===d.company_id&&u.department===d.name).length}}</td><td><button class="button dm-danger" @click="open('delete-department',{id:d.id,name:d.name,company_id:d.company_id,replacement_id:null})">Delete</button></td></tr></tbody></table></div><p v-if="!rows.length" class="dm-empty">No departments yet. Add a department to organise reports.</p><Pagination v-model:page="page" v-model:page-size="size" :total="rows.length"/></section></template>
<template v-else-if="section==='invitations'"><div v-if="inviteLink" class="dm-panel dm-share"><label>Secure invitation link<input :value="inviteLink" readonly @focus="($event.target as HTMLInputElement).select()"></label><p class="muted">One use · Expires in seven days · Uses the shared Judibas account.</p></div><section class="dm-panel dm-table-panel"><div class="dm-table-scroll"><table><thead><tr><th>Person</th><th>Company</th><th>Role</th><th>Status</th><th>Expires</th><th>Action</th></tr></thead><tbody><tr v-for="i in paged" :key="i.id"><td><strong>{{i.name||i.email}}</strong><small>{{i.email}}</small></td><td>{{companyName(i.access.daymark_company_id)}}</td><td>{{roleLabels[i.access.daymark_role]}}</td><td>{{i.accepted_at?'Accepted':i.revoked_at?'Revoked':new Date(i.expires_at)<new Date()?'Expired':'Pending'}}</td><td>{{new Date(i.expires_at).toLocaleDateString()}}</td><td><button v-if="!i.accepted_at&&!i.revoked_at&&new Date(i.expires_at)>new Date()" class="button" :disabled="busy" @click="submit('revoke',{id:i.id},'Invitation revoked.')">Revoke</button></td></tr></tbody></table></div><p v-if="!rows.length" class="dm-empty">No Daymark invitations yet.</p><Pagination v-model:page="page" v-model:page-size="size" :total="rows.length"/></section></template>
<template v-else-if="section==='roles'"><section class="dm-panel"><header><h3>Company roles</h3></header><div v-for="role in data.custom_roles" :key="role.id" class="dm-latest"><div><strong>{{role.name}}</strong><small>{{companyName(role.company_id)}} · {{roleLabels[role.base_role]}} · {{role.permissions.length}} permissions</small></div><button v-if="can('manage_roles')" class="button" @click="newRole(role)">Edit role</button></div><p v-if="!data.custom_roles.length" class="dm-empty">No custom roles. Built-in reporting roles are available.</p></section><section class="dm-panel dm-table-panel"><header><h3>Permission matrix</h3><p class="muted">Custom roles can restrict their base role, but cannot expand its data scope.</p></header><div class="dm-table-scroll"><table><thead><tr><th>Permission</th><th v-for="role in data.role_matrix?.roles" :key="role.role">{{roleLabels[role.role]}}</th></tr></thead><tbody><tr v-for="(label,key) in data.role_matrix?.abilities" :key="key"><td>{{label}}</td><td v-for="role in data.role_matrix.roles" :key="role.role">{{role.permissions.includes(key)?'✓':'—'}}</td></tr><tr><th>Data scope</th><td v-for="role in data.role_matrix?.roles" :key="role.role">{{role.scope}}</td></tr></tbody></table></div></section></template>
<template v-else-if="section==='audit'"><section class="dm-panel dm-table-panel"><div class="dm-table-scroll"><table><thead><tr><th>Person</th><th>Action</th><th>Details</th><th>When</th></tr></thead><tbody><tr v-for="a in paged" :key="a.id"><td>{{a.name}}</td><td>{{a.action}}</td><td>{{a.target}}</td><td>{{new Date(a.created_at).toLocaleString()}}</td></tr></tbody></table></div><p v-if="!rows.length" class="dm-empty">No activity yet.</p><Pagination v-model:page="page" v-model:page-size="size" :total="rows.length"/></section></template>
<template v-else-if="section==='account'"><section class="dm-panel dm-account"><h3>{{data.viewer.name}}</h3><p>{{data.viewer.email}}</p><p>{{roleLabels[data.viewer.role]}} · {{data.viewer.department}}</p><p class="muted">Your account is shared across your assigned Judibas products.</p><button v-if="data.viewer.role!=='super_admin'" class="button" @click="open('password',{current:'',password:'',password_confirmation:''})">Change password</button></section></template>
<template v-else-if="section==='settings'"><section class="dm-panel dm-account"><h3>Shared product settings</h3><p class="muted">Daymark uses the same email server, appearance and account settings as your other Judibas products.</p><a href="/admin#settings" class="button primary">Open shared settings ↗</a></section></template>
</main></div>
<AdminDialog v-if="dialog" :dialog-class="'dm-product-dialog '+(['report','review'].includes(dialog)?'dm-report-dialog ':'')+(dialog==='review'?'dm-review-dialog':'')" :title="dialog==='report'?reportTitle:dialog==='review'?'Daily report':dialog==='person'?'Manage reporting access':dialog==='invite'?'Invite to Daymark':dialog==='role'?(form.id?'Edit role':'Create role'):dialog==='department'?'Add department':dialog==='delete-department'?'Delete department':dialog==='daily-export'?'Day-end report':dialog==='password'?'Change shared password':'Report follow-up'" :busy="busy" @close="close"><div class="dm-dialog"><p v-if="modalError" class="notice admin-error" role="alert">{{modalError}}</p>
<form v-if="dialog==='report'" class="dm-report-form" @submit.prevent="saveReport('submitted')"><div v-if="reportReady" class="dm-report-state" role="status"><span class="dm-badge" :class="form.status||'draft'">{{form.id?textLabel(form.status):'New report'}}</span><strong>{{form.date}}</strong><p>{{reportHelp}}</p></div><div class="dm-form-grid"><label>Report date<input type="date" :value="form.date" :max="today" required :disabled="busy" @change="reportDate(($event.target as HTMLInputElement).value)"></label><label>Hours worked<input type="number" v-model.number="form.hours" min="0" max="24" step="0.25" required :disabled="form.status==='reviewed'"></label></div><p class="muted">One report per day. Existing reports open when you select their date. Drafts stay private.</p><div v-if="reportReady" class="dm-report-editor-grid"><div v-for="([key,label],index) in fields" :key="key" class="dm-field"><div class="dm-field-heading"><span class="dm-section-number">{{String(index+1).padStart(2,'0')}}</span><div><strong>{{label}}</strong><small>{{key==='completed'?'What did you finish?':key==='progress'?'What are you working on?':key==='plan'?'What comes next?':'Where do you need support?'}}</small></div></div><Editor :key="form.date+'-'+key" v-model="form[key]" :label="label" :readonly="busy||form.status==='reviewed'"/><small>Use “None” when there is nothing to report.</small></div></div><p v-if="form.status==='reviewed'" class="notice">This report is reviewed and locked. Ask your manager to request changes.</p><p v-if="form.feedback" class="notice">Reviewer feedback: {{form.feedback}}</p><div class="dm-dialog-actions"><button v-if="!form.status||form.status==='draft'" type="button" class="button" :disabled="busy||!reportReady" :aria-busy="savingReport==='draft'" @click="saveReport('draft')"><span v-if="savingReport==='draft'" class="dm-spinner" aria-hidden="true"></span>{{savingReport==='draft'?'Saving draft...':'Save private draft'}}</button><button class="button primary" :aria-busy="savingReport==='submitted'" :disabled="busy||!reportReady||form.status==='reviewed'"><span v-if="savingReport==='submitted'" class="dm-spinner" aria-hidden="true"></span>{{savingReport==='submitted'?'Submitting report...':busy&&!savingReport?'Loading...':reportButton}}</button></div></form>
<template v-else-if="dialog==='review'&&selected"><div class="dm-report-heading"><div><h3>{{selected.name}}</h3><p>{{selected.department}} · {{companyName(selected.company_id)}}</p></div><span class="dm-badge" :class="selected.status">{{textLabel(selected.status)}}</span></div><p class="muted">{{selected.date}} · {{Number(selected.hours).toFixed(1)}} hours</p><div class="dm-review-layout" :class="{'reading-only':!selected.feedback&&!ownDraft(selected)&&!(can('review_reports')&&selected.user_id!==data.viewer.id&&selected.status!=='draft')}"><div class="dm-report-reading" role="region" aria-label="Report content" tabindex="0"><section v-for="([key,label],index) in fields" :key="key" class="dm-report-section"><h4><span class="dm-section-number">{{String(index+1).padStart(2,'0')}}</span>{{label}}</h4><div class="dm-rich-text" v-html="selected.sections_html[key]"></div></section></div><aside v-if="selected.feedback||ownDraft(selected)||(can('review_reports')&&selected.user_id!==data.viewer.id&&selected.status!=='draft')" class="dm-review-sidebar" aria-label="Report feedback and actions"><p v-if="selected.feedback" class="notice">Reviewer feedback: {{selected.feedback}}</p><button v-if="ownDraft(selected)" class="button primary" @click="editOwn">Edit your report</button><form class="dm-review-form" v-if="can('review_reports')&&selected.user_id!==data.viewer.id&&selected.status!=='draft'" @submit.prevent="submit('review',form,'Review saved.')"><h4>Review this report</h4><p class="muted">Approve this update or request changes with clear feedback.</p><label>Review decision<select aria-label="Review decision" v-model="form.status"><option value="reviewed">Approve / Reviewed</option><option value="changes_requested">Request changes</option></select></label><label>Feedback<textarea v-model="form.feedback" rows="4" maxlength="5000" :required="form.status==='changes_requested'" placeholder="Add feedback or explain the changes needed"></textarea></label><div class="dm-dialog-actions"><button class="button primary" :disabled="busy">Save review</button></div></form></aside></div></template>
<form v-else-if="dialog==='department'" @submit.prevent="submit('departments',form,'Department saved.')"><label>Company<select v-model.number="form.company_id" required><option v-for="c in data.companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Department name<input v-model="form.name" required maxlength="200"></label><div class="dm-dialog-actions"><button class="button primary" :disabled="busy">Save department</button></div></form>
<form v-else-if="dialog==='delete-department'" @submit.prevent="submit('departments/delete',form,'Department deleted.')"><p>Delete <strong>{{form.name}}</strong>? Choose a replacement if people or pending invitations use this department.</p><label>Replacement department<select v-model.number="form.replacement_id"><option :value="null">No replacement</option><option v-for="d in data.departments.filter((d:any)=>d.company_id===form.company_id&&d.id!==form.id)" :key="d.id" :value="d.id">{{d.name}}</option></select></label><div class="dm-dialog-actions"><button class="button dm-danger" :disabled="busy">Delete department</button></div></form>
<form v-else-if="dialog==='person'||dialog==='invite'" @submit.prevent="dialog==='invite'?invite():submit('user',{...form,department:data.departments.find((d:any)=>d.id===form.department_id)?.name||form.department},'Reporting access saved.')"><p v-if="dialog==='person'"><strong>{{form.name}}</strong><br>{{form.email}}</p><div class="dm-form-grid"><template v-if="dialog==='invite'"><label>Name<input v-model="form.name" required maxlength="100"></label><label>Email<input type="email" v-model="form.email" required maxlength="200"></label><label>Company<select v-model.number="form.company_id" required @change="form.department_id='';form.custom_role_id=null;form.manager_ids=[];inlineDepartmentName='';addingDepartment=false"><option v-for="c in data.companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label></template><label>Department<select aria-label="Reporting department" v-model.number="form.department_id" required><option value="">Select department</option><option v-for="d in data.departments.filter((d:any)=>d.company_id===form.company_id)" :key="d.id" :value="d.id">{{d.name}}</option></select><button v-if="can('manage_departments')" type="button" class="dm-inline-department-toggle" @click="addingDepartment=!addingDepartment;inlineDepartmentName=''">Add a new department</button></label><div v-if="addingDepartment&&can('manage_departments')" class="dm-inline-department"><label>New department name<input v-model="inlineDepartmentName" maxlength="200" placeholder="For example, Design" @keydown.enter.prevent="createInlineDepartment"></label><button type="button" class="button" :disabled="busy" @click="createInlineDepartment">Add and select</button></div><label>Designation<input v-model="form.designation" required maxlength="200"></label><label>Reporting role<select v-model="form.role"><option v-for="(label,key) in roleLabels" v-show="key!=='super_admin'" :key="key" :value="key">{{label}}</option></select></label><label>Custom role<select v-model.number="form.custom_role_id"><option :value="null">Use reporting role</option><option v-for="r in data.custom_roles.filter((r:any)=>r.company_id===form.company_id)" :key="r.id" :value="r.id">{{r.name}}</option></select></label></div><fieldset><legend>Reporting managers</legend><label class="dm-check" v-for="u in data.users.filter((u:any)=>u.company_id===form.company_id&&u.id!==form.id&&u.active&&['pm','om'].includes(u.role))" :key="u.id"><input type="checkbox" v-model="form.manager_ids" :value="u.id">{{u.name}} · {{roleLabels[u.role]}}</label><p v-if="!data.users.some((u:any)=>u.company_id===form.company_id&&u.active&&['pm','om'].includes(u.role))" class="muted">No active PM or OM in this company.</p></fieldset><label v-if="dialog==='person'" class="dm-check"><input type="checkbox" v-model="form.active">Daymark profile active (other products are unchanged)</label><label v-if="dialog==='invite'">Delivery<select v-model="form.delivery_method"><option value="manual">Create secure invitation link</option><option value="email">Send using shared email settings</option></select></label><div class="dm-dialog-actions"><button class="button primary" :disabled="busy">{{dialog==='invite'?'Create invitation':'Save reporting access'}}</button></div></form>
<form v-else-if="dialog==='role'" @submit.prevent="submit('roles',form,'Role saved.')"><div class="dm-form-grid"><label>Company<select v-model.number="form.company_id" :disabled="!!form.id" required><option v-for="c in data.companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Role name<input v-model="form.name" required maxlength="100"></label><label>Base role<select v-model="form.base_role" :disabled="!!form.id" @change="form.permissions=['view_reports']"><option v-for="role in data.role_matrix.roles.filter((r:any)=>r.role!=='super_admin')" :key="role.role" :value="role.role">{{roleLabels[role.role]}}</option></select></label></div><p class="muted">Permissions can be restricted within the base role. Data access always follows its company or assigned-person scope.</p><fieldset><legend>Allowed actions</legend><label class="dm-check" v-for="key in roleAbilities" :key="key"><input type="checkbox" v-model="form.permissions" :value="key">{{data.role_matrix.abilities[key]}}</label></fieldset><div class="dm-dialog-actions"><button class="button primary" :disabled="busy">Save role</button></div></form>
<form v-else-if="dialog==='daily-export'" @submit.prevent="download('daily-export','pdf')"><p class="muted">Download submitted reports grouped by company, department and person. Private drafts are excluded.</p><label>Report date<input v-model="form.date" type="date" :max="today" required></label><div class="dm-form-grid"><label>Company<select aria-label="Export company" v-model="form.export_company" @change="form.export_department=''"><option value="">All accessible companies</option><option v-for="c in data.companies" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label><label>Department<select aria-label="Export department" v-model="form.export_department"><option value="">All departments</option><option v-for="d in exportDepartments" :key="d">{{d}}</option></select></label></div><div class="dm-dialog-actions"><button type="button" class="button" :disabled="busy" @click="download('daily-export','xlsx')" :aria-busy="downloading==='daily-export:xlsx'"><span v-if="downloading==='daily-export:xlsx'" class="dm-spinner" aria-hidden="true"></span>{{downloading==='daily-export:xlsx'?'Preparing Excel...':'Download Excel'}}</button><button class="button primary" :disabled="busy" :aria-busy="downloading==='daily-export:pdf'"><span v-if="downloading==='daily-export:pdf'" class="dm-spinner" aria-hidden="true"></span>{{downloading==='daily-export:pdf'?'Preparing PDF...':'Download PDF'}}</button></div></form>
<form v-else-if="dialog==='password'" @submit.prevent="submit('password',form,'Password changed.')"><label>Current password<input v-model="form.current" type="password" required autocomplete="current-password"></label><label>New password<input v-model="form.password" type="password" required minlength="12" autocomplete="new-password"></label><label>Confirm password<input v-model="form.password_confirmation" type="password" required minlength="12" autocomplete="new-password"></label><div class="dm-dialog-actions"><button class="button primary" :disabled="busy">Update shared password</button></div></form>
<template v-else-if="dialog==='action'"><p>{{form.name}} · {{form.date}}</p><p>{{form.feedback||'Open the daily report to follow up.'}}</p><button class="button primary" @click="savedFilters.reports={};date=form.date;company='';employee='';department='';status='';search='';close();go('reports')">Open daily reports</button></template>
</div></AdminDialog>
</div></template>
